/* Service worker for the installed copy. Generated by build.py — the version
   below is a hash of what it caches, so a deploy that changes nothing leaves
   the phone's copy alone, and one that changes anything replaces it whole.

   The dictionary is 4 MB and the whole point of installing is to be able to
   look a word up on the underground, so index.html and data.json are taken in
   on install rather than waiting to be asked for. */
var VERSION = '6481b390b68f';
var CACHE = 'engrowdict-' + VERSION;
var SHELL = [
  './',
  './index.html',
  './data.json',
  './manifest.webmanifest',
  './icon-180.png',
  './icon-192.png',
  './icon-512.png'
];

self.addEventListener('install', function (e) {
  e.waitUntil(
    caches.open(CACHE)
      .then(function (c) { return c.addAll(SHELL); })
      .then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener('activate', function (e) {
  e.waitUntil(
    caches.keys().then(function (names) {
      return Promise.all(names.map(function (n) {
        return n === CACHE ? null : caches.delete(n);
      }));
    }).then(function () { return self.clients.claim(); })
  );
});

self.addEventListener('fetch', function (e) {
  var req = e.request;
  if (req.method !== 'GET') return;                 // writing goes to Apps Script
  var url = new URL(req.url);
  if (url.origin !== self.location.origin) return;  // the sheet, the dictionaries
  if (url.search) return;                           // data.json?ts=… after a Sync

  // A tab opened with no network still gets the page it had.
  if (req.mode === 'navigate') {
    e.respondWith(
      fetch(req).catch(function () {
        return caches.match('./index.html', { ignoreSearch: true });
      })
    );
    return;
  }

  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then(function (hit) {
      var live = fetch(req).then(function (res) {
        if (res && res.ok) {
          var copy = res.clone();
          caches.open(CACHE).then(function (c) { c.put(req, copy); });
        }
        return res;
      }).catch(function () { return hit; });
      return hit || live;      // what is held wins; the fresh copy lands behind it
    })
  );
});
